Given a string s consisting of only lowercase alphabets, for each index i in the string (0 ≤ i < n), find the first non-repeating character in the prefix s[0..i]. If no such character exists, use '#'.Examples:Input: s = "aabc"Output: a#bbExplanation: At i=0 ("a"): First non-repeating character is 'a'.At i=1 ("aa"): No non-repeating character, so '#'.At i=2 ("aab"): First non-repeating character is 'b'.At i=3 ("aabc"): Non-repeating characters are 'b' and 'c'; 'b' appeared first, so 'b'. Input: s = "bb" Output: "b#" Explanation: At i=0 ("b"): First non-repeating character is 'b'.At i=1 ("bb"): No non-repeating character, so '#'.Try It YourselfTable of Content[Naive Approach] Nested Loop - O(n ^ 2) time and O(n) space[Better Approach] Queue and Frequency Array - O(n) Time and O(n) Space[Expected Approach] Frequency and First Occurrence Arrays – O(26 * n) Time and O(1) Space[Naive Approach] Nested Loop - O(n ^ 2) time and O(n) spaceThe idea is to use a frequency array to count character occurrences and scan the processed part of the string to find the first non-repeating character.Update the frequency of the current character.Scan from the beginning and append the first character with frequency 1; if none exists, append '#'.Repeat for each character and return the result.
            C++

    #include <iostream>
#include <string>
#include <vector>
using namespace std;

string firstNonRepeating(string &s)
{
    string ans;
    int n = s.size();

    // frequency vector for all ASCII characters
    vector<int> freq(26, 0);

    // Process each character in the stream
    for (int i = 0; i < n; i++)
    {

        // Update frequency for the current character
        freq[s[i] - 'a']++;

        // Scan from the beginning to find the first non-repeating character
        bool found = false;

        for (int j = 0; j <= i; j++)
        {
            if (freq[s[j] - 'a'] == 1)
            {
                ans.push_back(s[j]);
                found = true;
                break;
            }
        }

        if (!found)
        {
            ans.push_back('#');
        }
    }

    return ans;
}

int main()
{
    string s = "aabc";
    string ans = firstNonRepeating(s);
    cout << ans << endl;
    return 0;
}


