        int[] count = new int[26];

        Queue<Character> q = new LinkedList<>();

        for (int i = 0; i < s.length(); i++) {

            // if non-repeating element found push it in
            // queue
            if (count[s.charAt(i) - 'a'] == 0) {
                q.add(s.charAt(i));
            }
            count[s.charAt(i) - 'a']++;

            // if front element is repeating pop it from the
