            while (!q.isEmpty()
                   && count[q.peek() - 'a'] > 1) {
                q.poll();
            }

            // if queue is not empty append front
            // element else append "#" in ans string.
            if (!q.isEmpty()) {
                ans.append(q.peek());
            }
            else {
                ans.append('#');
            }
        }

        return ans.toString();
    }

