class GFG {
    string firstNonRepeating(string s)
    {
        StringBuilder ans = new StringBuilder();
        int[] count = new int[26];
        Queue<char> q = new Queue<char>();

        for (int i = 0; i < s.Length; i++) {
            if (count[s[i] - 'a'] == 0)
                q.Enqueue(s[i]);

            count[s[i] - 'a']++;

            while (q.Count > 0 && count[q.Peek() - 'a'] > 1)
                q.Dequeue();

            if (q.Count > 0)
                ans.Append(q.Peek());
            else
                ans.Append('#');
        }

        return ans.ToString();
    }

